import dace
from dace.sdfg import nodes
from dace.codegen.targets.cpp import cpp_offset_expr
from dace.codegen.codeobject import CodeObject
from dace.codegen.prettycode import CodeIOStream
from dace.codegen.targets.framecode import CppxFusion

# ATPUAttentionNode definíciója
@dace.library.node
class ATPUAttentionNode(nodes.LibraryNode):
    implementations = {}
    default_implementation = None

    def __init__(self, name, d_model, *args, **kwargs):
        super().__init__(name, *args, inputs={'q_in', 'k_in', 'v_in'}, outputs={'out'}, **kwargs)
        self.d_model = d_model

# Kódgenerátor regisztrálása az ATPUAttentionNode-hoz
@dace.library.expansion
class ExpandATPUAttention(dace.library.Expansion):
    environments =

    @staticmethod
    def expansion(node, parent_state, parent_sdfg):
        # Ez a függvény egy alacsonyabb szintű SDFG-t generálhatna,
        # vagy üresen hagyható, ha a kódgenerálás közvetlenül történik.
        # Itt most az utóbbit választjuk.
        return None

# C++ kódgenerátor az ATPUAttentionNode-hoz
@dace.library.implementations
class ImplATPUAttention(dace.library.Implementation):
    @staticmethod
    def code(node, state, sdfg, stream: CodeIOStream, function_stream: CodeIOStream):
        q_ptr = cpp_offset_expr(sdfg.arrays[state.in_edges(node).data.data],
                                state.in_edges(node).data.subset)
        k_ptr = cpp_offset_expr(sdfg.arrays[state.in_edges(node).data.data],
                                state.in_edges(node).data.subset)
        #... és így tovább a többi bemenethez és kimenethez

        # Itt generáljuk azt a C++ kódot, ami az LLVM backendünket hívja meg
        # az `ATTN.MQ` utasítás végrehajtásához.
        # Ez történhet inline assembly-n vagy LLVM intrinsic-eken keresztül.
        stream.write(f"""
        {{
            // Pointerek átadása a regiszterekbe
            uint64_t q_addr = (uint64_t)({q_ptr});
            uint64_t kv_addr = (uint64_t)({k_ptr});
            uint64_t out_addr;

            // Inline assembly az ATTN.MQ utasítás hívásához
            asm volatile(
                "attn.mq %0, %1, %2"
                : "=r"(out_addr)
                : "r"(q_addr), "r"(kv_addr)
                : "memory"
            );

            // Az eredmény pointert (out_addr) a kimeneti pufferre kell irányítani.
            // A valóságban ez bonyolultabb memóriakezelést igényel.
        }}
        """)

    implementations = {
        "atpu_cpp": (ImplATPUAttention, [" "])
    }

