# CompCert fordító beállítása
CC = ccomp
CFLAGS = -O2 -g

# Forrásfájlok (feltételezzük, hogy a kremlin generálta őket)
SRCS = memory.c scheduler.c driver.c
OBJS = $(SRCS:.c=.o)

# Fő végrehajtható
TARGET = aethelred_runtime_test

.PHONY: all clean

all: $(TARGET)

$(TARGET): $(OBJS)
	$(CC) $(CFLAGS) -o $@ $^

%.o: %.c
	$(CC) $(CFLAGS) -c $< -o $@

clean:
	rm -f $(OBJS) $(TARGET)

