// FILE: kernels/preprocessing.sac
// SZAKASZ 5.4: Nagy Teljesítményű Kernelek Implementációja
//
// Adat-előfeldolgozó kernel implementációja SaC (Single Assignment C) nyelven.
// A SaC egy funkcionális, adat-párhuzamos nyelv, amely a C-szerű szintaxist
// kombinálja a tömbprogramozás magas szintű absztrakcióival. [span_9](start_span)[span_9](end_span)
// Különösen alkalmas olyan számítás-intenzív feladatokra, amelyek
// többdimenziós tömbökön végeznek műveleteket.
//
// Ez a kernel egy bemeneti adatmátrixot normalizál (z-score normalizálás).
//
// Fordítás: sac2c -O3 preprocessing.sac
//-----------------------------------------------------------------------------
#include "sac.h"

// A `with` ciklus egy tömb-komprehenzió, amely párhuzamosan hajtódik végre.
int[*] normalize(int[*] data)
{
    // 1. Átlag számítása
    // A `fold` egy redukciós művelet.
    avg = fold(+, 0, data) / shape(data);

    // 2. Szórás számítása
    // A `genarray` egy új tömböt hoz létre a megadott dimenziókkal.
    diffs = with (. <= [i] < shape(data) )
            genarray( shape(data), (data[i] - avg) * (data[i] - avg) );
    stdev = isqrt( fold(+, 0, diffs) / shape(data) );

    // 3. Normalizálás
    // A `modarray` egy létező tömböt módosít (itt a `data` másolatát).
    normalized_data = with (. <= [i] < shape(data) )
                      modarray( data, [i]: (data[i] - avg) / stdev );

    return( normalized_data);
}

