// FILE: runtime/memory.fst
// SZAKASZ 6: Az Aethelred Futtatókörnyezet és Rendszerkönyvtárak
//
// Az ATPU számára dedikált memória-allokátor implementációja Low*/F* nyelven.
// A Low* egy az F*-ba ágyazott DSL, amely C-szintű kontrollt biztosít a memória
// felett, de az F* függő típusrendszerén keresztül garantálja a memória-biztonságot. [span_10](start_span)[span_10](end_span)[span_11](start_span)[span_11](end_span)
//
// Ez a modul egy egyszerű "bump" allokátort valósít meg egy előre lefoglalt
// memóriaterületen (heap). A típusrendszer biztosítja, hogy soha ne történjen
// túl-allokálás vagy érvénytelen pointerrel való művelet.
//-----------------------------------------------------------------------------
module Runtime.Memory

open FStar.Heap
open FStar.Buffer
open LowStar.Buffer
open LowStar.Monotonic.Buffer

// A memória modellje. A Low* egy CompCert-szerű strukturált memória modellt használ. [span_12](start_span)[span_12](end_span)
type mem = heap

// Az ATPU számára fenntartott memóriaterület (heap) mérete
let atpu_heap_size = 1024 * 1024 // 1 MB

// A heap-et reprezentáló buffer
let atpu_heap : buffer (uint8_t) = create (u8 0) atpu_heap_size

// A "bump pointer", ami a következő szabad memóriaterületre mutat
let atpu_heap_ptr : mref nat atpu_heap = mcreate 0

// Típusdefiníció egy érvényes pointerre az ATPU heap-en belül
type atpu_ptr (a:Type) = b:buffer a{ within_atpu_heap b }

// Segédfüggvény annak ellenőrzésére, hogy egy buffer a heap-en belül van-e
let within_atpu_heap (b:buffer 'a) : bool =
    let start_addr = addr_of atpu_heap in
    let end_addr = start_addr `addr_add` atpu_heap_size in
    (addr_of b >= start_addr) && ((addr_of b `addr_add` (length b)) <= end_addr)

// Memória allokálása az ATPU heap-en
// A függvény típusa garantálja:
// 1. A visszaadott pointer nem null.
// 2. A visszaadott pointer a heap-en belülre mutat.
// 3. A heap pointer (`atpu_heap_ptr`) helyesen frissül.
// 4. A függvény hatása (ST) tiszta, kivéve a memória módosítását.
val atpu_malloc: #a:Type -> size:size_t -> ST (atpu_ptr a)
  (requires (fun h -> size > 0 /\!atpu_heap_ptr + size <= atpu_heap_size))
  (ensures (fun h0 p h1 ->
    modifies (loc_union (loc_buffer atpu_heap) (loc_mref atpu_heap_ptr)) h0 h1 /\
   !atpu_heap_ptr `in` h1 =!atpu_heap_ptr `in` h0 + size /\
    within_atpu_heap p
  ))
let atpu_malloc #a size =
  let offset =!atpu_heap_ptr in
  atpu_heap_ptr := offset + size;
  let p = sub atpu_heap offset size in
  // A `cast_buffer` biztonságosságát az F* típusellenőrzője garantálja
  cast_buffer p

