; az optimális (minimális költségű) eszközt választja.
(define (spec t decision)
  (assert
    (let ([chosen-cost (if (eq? decision 'CPU) (cpu-cost t) (atpu-cost t))]
          [optimal-cost (min (cpu-cost t) (atpu-cost t))])
      (= chosen-cost optimal-cost))))

