-- SZAKASZ 7.3: Algoritmikus Komponensek Verifikációja
--
-- A figyelem-mechanizmus matematikai tulajdonságainak bizonyítása Lean 4-ben.
-- A Lean 4 egy modern, hatékony interaktív tételbizonyító és funkcionális
-- programozási nyelv. [span_26](start_span)[span_26](end_span)
--
-- Itt azt a tulajdonságot bizonyítjuk, hogy a softmax függvény által generált
-- figyelem-súlyok összege mindig 1, ami elengedhetetlen a valószínűségi
-- értelmezéshez.
-----------------------------------------------------------------------------
import Mathlib.Data.Real.Basic
import Mathlib.Analysis.SpecialFunctions.Exp

-- Definíciók
def softmax (v : Fin n → ℝ) : Fin n → ℝ :=
  fun i => Real.exp (v i) / (Finset.sum Finset.univ fun j => Real.exp (v j))

-- A tétel: A softmax kimeneti vektor elemeinek összege 1.
theorem softmax_sum_is_one (v : Fin n → ℝ) :
  (Finset.sum Finset.univ fun i => softmax v i) = 1 := by
  -- A bizonyítás lépései:
  -- 1. Behelyettesítjük a softmax definícióját.
  unfold softmax
  -- 2. Átrendezzük az összeget, hogy a nevezőt kiemeljük.
  rw [Finset.sum_div]
  -- 3. Egyszerűsítjük a számlálót és a nevezőt, ami megegyezik.
  apply div_self
  -- 4. Bizonyítani kell, hogy a nevező nem nulla, ami igaz, mert az exp függvény mindig pozitív.
  apply Finset.sum_ne_zero_of_nonneg
  intro i _
  exact Real.exp_pos (v i)

// FILE: proofs/data_pipeline.dfy
// SZAKASZ 7.3: Algoritmikus Komponensek Verifikációja
//
// Egy egyszerű, de verifikált adatfeldolgozó folyamat implementációja Dafny-ban.
// A Dafny egy "verification-aware" programozási nyelv, amely a specifikációkat
// (elő- és utófeltételek, invariánsok) a kód szerves részévé teszi. [span_27](start_span)[span_27](end_span)[span_28](start_span)[span_28](end_span)
// A beépített statikus verifikáló (amely a Z3 SMT szolverre épül) automatikusan
// ellenőrzi a specifikációk teljesülését.
//-----------------------------------------------------------------------------
method Main() {
    var a := new int;
    a, a, a, a, a := 1, -2, 3, -4, 5;

    var positive_array := FilterPositives(a);

    // Az utófeltétel garantálja, hogy a `positive_array` minden eleme pozitív.
    assert forall i :: 0 <= i < positive_array.Length ==> positive_array[i] > 0;
    print "Verification successful.";
}

// Ez a metódus kiszűri a pozitív elemeket egy tömbből.
method FilterPositives(arr: array<int>) returns (result: array<int>)
    // Előfeltétel: a bemeneti tömb nem lehet null.
    requires arr!= null
    // Utófeltétel: a kimeneti tömb minden eleme nagyobb, mint 0.
    ensures forall i :: 0 <= i < result.Length ==> result[i] > 0
    // Utófeltétel: a kimeneti tömb hossza nem nagyobb, mint a bemenetié.
    ensures result.Length <= arr.Length
{
    var positive_elements := new seq<int>(0);

    // A ciklus végigiterál a bemeneti tömbön.
    for i := 0 to arr.Length
        // Ciklusinvariáns: a `positive_elements` szekvencia minden eleme pozitív.
        invariant 0 <= i <= arr.Length
        invariant forall j :: 0 <= j < |positive_elements| ==> positive_elements[j] > 0
    {
        if arr[i] > 0 {
            positive_elements := positive_elements + [arr[i]];
        }
    }

    // A szekvenciát tömbbé alakítjuk.
    result := new int[|positive_elements|];
    for i := 0 to |positive_elements|
        invariant 0 <= i <= |positive_elements|
    {
        result[i] := positive_elements[i];
    }
}

