-- FILE: kernels/attention.fut
-- SZAKASZ 5.4: Nagy Teljesítményű Kernelek Implementációja
--
-- A figyelem-mechanizmus magjának implementációja Futhark nyelven.
-- A Futhark egy tisztán funkcionális, adat-párhuzamos tömbnyelv, amely
-- hatékony GPU (és a mi esetünkben ATPU) kódra fordul. [span_4](start_span)[span_4](end_span)
-- Ez a kód magas szinten, deklaratívan írja le a párhuzamos számítást,
-- elrejtve az alacsony szintű optimalizálás bonyolultságát.
--
-- Ez a kód a "Attention is All You Need" [span_5](start_span)[span_5](end_span)[span_6](start_span)[span_6](end_span) cikkben leírt
-- skálázott dot-product figyelem-mechanizmust valósítja meg.
--
-- Fordítás: futhark c --library attention.fut
-----------------------------------------------------------------------------
module attention

-- Egyetlen figyelem-fej számítása.
-- q: egyetlen query vektor
-- k: key mátrix (seq_len x d_k)
-- v: value mátrix (seq_len x d_v)
-- returns: egyetlen kontextus vektor (d_v méretű)
entry scaled_dot_product_attention [seq_len][d_k][d_v]
    (q: [d_k]f32)
    (k: [seq_len][d_k]f32)
    (v: [seq_len][d_v]f32): [d_v]f32 =
  let d_k_f32 = f32.i32 d_k
  let scale = 1.0f32 / sqrt d_k_f32

  -- 1. Pontszámok (scores) számítása: q @ K.T
  -- A `map` párhuzamosan alkalmazza a dot-product műveletet a K mátrix minden sorára.
  let scores = map (\k_row -> reduce (+) 0f32 (map2 (*) q k_row)) k

  -- 2. Skálázás
  let scaled_scores = map (* scale) scores

  -- 3. Softmax
  let max_score = reduce f32.max f32.neginf scaled_scores
  let exps = map (\s -> exp (s - max_score)) scaled_scores
  let sum_exps = reduce (+) 0f32 exps
  let attention_weights = map (/ sum_exps) exps

  -- 4. Értékek (values) súlyozott összege
  -- Először minden value vektort megszorzunk a megfelelő súllyal.
  let weighted_vs = map2 (\weight v_row -> map (* weight) v_row) attention_weights v
  -- Majd összegezzük a súlyozott vektorokat elemenként.
  let context_vector = reduce (map2 (+)) (replicate d_v 0f32) weighted_vs
  in context_vector

