    // 3. Ellenőrizzük a digitális aláírást a tárolt hash-en.
    let sig_is_valid = verify_ecdsa pubKey img.hash img.signature
    // 4. A betöltés csak akkor érvényes, ha mindkét feltétel teljesül.
    (hash_matches && sig_is_valid)

